import java.util.*;

class Solution {
    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        for (int skip = n - 1; skip >= 0; skip--) {
            List<List<Integer>> adj = new ArrayList<>();
            for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
            for (int j = 0; j < n; j++) {
                if (j == skip) continue;
                adj.get(edges[j][0]).add(edges[j][1]);
                adj.get(edges[j][1]).add(edges[j][0]);
            }

            boolean[] visited = new boolean[n + 1];
            int count = bfs(adj, visited);
            if (count == n) return new int[]{edges[skip][0], edges[skip][1]};
        }
        return new int[0];
    }

    private int bfs(List<List<Integer>> adj, boolean[] visited) {
        Deque<Integer> queue = new ArrayDeque<>();
        queue.add(1);
        visited[1] = true;
        int count = 1;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj.get(u)) {
                if (visited[v]) continue;
                visited[v] = true;
                count++;
                queue.add(v);
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    private List<List<int[]>> adj;
    private boolean[] visited;
    private int[] fromEdge;
    private List<Integer> cycleEdges;

    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int j = 0; j < n; j++) {
            adj.get(edges[j][0]).add(new int[]{edges[j][1], j});
            adj.get(edges[j][1]).add(new int[]{edges[j][0], j});
        }

        visited = new boolean[n + 1];
        fromEdge = new int[n + 1];
        Arrays.fill(fromEdge, -1);
        cycleEdges = new ArrayList<>();

        dfs(1, -1);

        int best = -1;
        for (int id : cycleEdges) best = Math.max(best, id);
        return new int[]{edges[best][0], edges[best][1]};
    }

    private boolean dfs(int u, int parentEdge) {
        visited[u] = true;
        for (int[] e : adj.get(u)) {
            int v = e[0];
            int id = e[1];
            if (id == parentEdge) continue;
            if (visited[v]) {
                if (cycleEdges.isEmpty()) {
                    cycleEdges.add(id);
                    int cur = u;
                    while (cur != v && fromEdge[cur] != -1) {
                        cycleEdges.add(fromEdge[cur]);
                        cur = cyclePrev(cur, fromEdge[cur]);
                    }
                }
                continue;
            }
            fromEdge[v] = id;
            if (dfs(v, id)) return true;
        }
        return false;
    }

    private int cyclePrev(int node, int edgeId) {
        for (int[] e : adj.get(node)) {
            if (e[1] == edgeId) return e[0];
        }
        return node;
    }
}

import java.util.*;

class Solution {
    private int[] parent;

    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        parent = new int[n + 1];
        for (int i = 1; i <= n; i++) parent[i] = i;

        for (int[] e : edges) {
            int ru = find(e[0]);
            int rv = find(e[1]);
            if (ru == rv) return new int[]{e[0], e[1]};
            parent[ru] = rv;
        }
        return new int[0];
    }

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
}
